public class SigmoidUnitTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static double round6(double x) {
        return Math.round(x * 1000000.0) / 1000000.0;
    }

    static String rounded(double[] values) {
        if (values == null) {
            return "null";
        }
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < values.length; i++) {
            if (i > 0) {
                sb.append(", ");
            }
            sb.append(round6(values[i]));
        }
        return sb.append("]").toString();
    }

    public static void main(String[] args) {
        try {
            check("sigmoid(0)", 0.5, round6(SigmoidUnit.sigmoid(0)));
            check("sigmoid(1)", 0.731059, round6(SigmoidUnit.sigmoid(1)));
            check("sigmoid(-1)", 0.268941, round6(SigmoidUnit.sigmoid(-1)));
            check("derivative(0) is the maximum slope", 0.25, round6(SigmoidUnit.derivative(0)));
            check("derivative(1)", 0.196612, round6(SigmoidUnit.derivative(1)));
            check("derivative(-3)", 0.045177, round6(SigmoidUnit.derivative(-3)));
            check("applyAll({-1, 0, 1})", "[0.268941, 0.5, 0.731059]",
                    rounded(SigmoidUnit.applyAll(new double[]{-1, 0, 1})));
            check("applyAll({}) stays empty", "[]", rounded(SigmoidUnit.applyAll(new double[]{})));
        } catch (RuntimeException e) {
            System.out.println("FAIL  unexpected exception -- expected none but got " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

